'use strict';

// MODULES //

var equal = require( '@data-apis/canonical/equal' );
var indexRecord = require( '@data-apis/record/index-record' );


// MAIN //

/**
* Validates an index row against its stored envelope.
*
* @param {Object} row - index row
* @param {Object} envelope - stored record
* @param {string} recordPath - path relative to data
* @param {Object} [options] - validation options
* @throws {Error} if the values disagree
*/
function validateIndexRow( row, envelope, recordPath, options ) {
	var derived = indexRecord( envelope, recordPath, options );

	if ( !equal( row, derived ) ) {
		throw new Error( 'Index row does not agree with stored envelope: ' + recordPath );
	}
}


// EXPORTS //

module.exports = validateIndexRow;
